// Generating a first `tests.map` from a project's own conventions
// (Client ruling: "Generated by a Fabrica command from the project's
// conventions, committed, hand-editable afterwards").
//
// The one convention this reads is colocation - `foo.ts` beside
// `foo.test.ts` - which is the convention this project itself documents
// and the one the Client named. Two lines come out of each test file:
//
//   foo.ts:      foo.test.ts     (when a colocated source exists)
//   foo.test.ts: foo.test.ts
//
// The second is not redundant. Under the colocated convention almost
// every task edits a test file as well as its source, and a test file no
// pattern matches would be reported as unmapped on nearly every
// delivery - which would turn the unmapped report into noise instead of
// a signal.
//
// What is deliberately NOT generated: a folder-wide fallback for a
// source file that has no colocated test of its own. Those files stay
// unmapped, and that is the honest answer - the map says what the
// convention knows, and the delivery then names them, which is exactly
// the gap worth seeing. The file is hand-editable afterwards for the
// cases where a human knows what actually covers one.

import { readdirSync } from "node:fs";
import { join, relative, sep } from "node:path";

import { TEST_FILENAME } from "./classify.ts";
import { TEST_MAP_FILENAME } from "./parse.ts";
import type { TestMapEntry } from "./types.ts";

/** Directories never walked: build output and dependency trees, plus
 * every dotted directory (`.git`, `.github`, a harness's own settings
 * folder), none of which hold a project's own tests. */
export const IGNORED_DIRECTORIES: readonly string[] = ["node_modules", "dist", "build", "coverage", "out", "vendor"];

/**
 * The entries a `tests.map` for `projectPath` starts out as, sorted by
 * pattern so the committed file reads in a stable order and a
 * regeneration produces a reviewable diff rather than a reshuffle.
 */
export function generateTestMap(projectPath: string): TestMapEntry[] {
  const byPattern = new Map<string, string[]>();

  const add = (pattern: string, test: string): void => {
    const tests = byPattern.get(pattern);
    if (tests === undefined) byPattern.set(pattern, [test]);
    else if (!tests.includes(test)) tests.push(test);
  };

  const files = new Set(listFiles(projectPath, projectPath));
  for (const file of files) {
    const name = file.slice(file.lastIndexOf("/") + 1);
    const match = TEST_FILENAME.exec(name);
    if (match === null) continue;
    // A test file always covers itself.
    add(file, file);
    const source = `${file.slice(0, file.length - name.length)}${match[1]}.${match[2]}`;
    if (files.has(source)) add(source, file);
  }

  return [...byPattern.entries()]
    .sort(([left], [right]) => (left < right ? -1 : left > right ? 1 : 0))
    .map(([pattern, tests], index) => ({ pattern, tests: [...tests].sort(), line: index + 1 }));
}

/** The comment block a generated map opens with: what the format is, how
 * matching works, and that editing it by hand is expected rather than
 * tolerated. Written into the committed file so the next person to read
 * it needs nothing else. */
export function generatedHeader(): string {
  return [
    `# ${TEST_MAP_FILENAME} - which tests cover which files.`,
    "#",
    "# One entry per line: a glob pattern, a colon, then comma-separated",
    "# test files or commands. Blank lines and lines starting with # are",
    "# comments.",
    "#",
    "#   src/foreman/do.ts: src/foreman/do.test.ts",
    "#   src/cli/*.ts: npm test -- src/cli",
    "#",
    "# Wildcards: * and ? stay inside one path segment, ** crosses",
    "# directories (and **/ also matches no directory at all). A touched",
    "# file takes the union of EVERY entry it matches, so adding a line",
    "# can only ever add tests to a run.",
    "#",
    "# Fabrica names the matching tests in each task's brief, tells the",
    "# worker to run exactly those first and the whole suite afterwards,",
    "# and reports on the delivery which of them the worker says it ran,",
    "# plus any touched CODE file this file maps to nothing. Documentation",
    "# never counts as unmapped (any *.md, anything under notes/ or docs/,",
    "# and the root's own dotfiles and LICENSE), and a test file counts as",
    "# covering itself even with no line here.",
    "#",
    "# Generated by `fabrica tests-map` from this project's colocated",
    "# foo.ts / foo.test.ts convention. Editing it by hand is expected:",
    "# a source file with no colocated test of its own is left out, so",
    "# add a mapping here when you know what actually covers one.",
    "# Re-running the command needs --force and discards those edits.",
  ].join("\n");
}

/** Every file under `dir`, project-relative and "/"-separated. */
function listFiles(dir: string, projectPath: string): string[] {
  const found: string[] = [];
  for (const item of readdirSync(dir, { withFileTypes: true })) {
    if (item.isDirectory()) {
      if (item.name.startsWith(".") || IGNORED_DIRECTORIES.includes(item.name)) continue;
      found.push(...listFiles(join(dir, item.name), projectPath));
      continue;
    }
    if (!item.isFile()) continue;
    found.push(relative(projectPath, join(dir, item.name)).split(sep).join("/"));
  }
  return found;
}
